const e = React.createElement;
const dur = Math.max(2, durationInFrames);

const brandText = 'INCORRECT WHEN UNSURE';
const framesPerLetter = 2;

const shardCount = 5;
const shards = Array.from({length: shardCount}, function(_, i) {
  const angle = (i / shardCount) * Math.PI * 2 + 0.7;
  const baseDist = 100 + i * 35;
  const driftDist = interpolate(frame, [0, dur], [baseDist, baseDist + 70 + i * 25], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
  const shardOpacity = interpolate(frame, [0, dur], [0.22 - i * 0.03, 0.03], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
  const cx = width * 0.5 + Math.cos(angle) * driftDist;
  const cy = height * 0.36 + Math.sin(angle) * driftDist * 0.6;
  const rot = interpolate(frame, [0, dur], [i * 25, i * 25 + 20], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
  return e('div', {
    key: 'sh' + i,
    style: {
      position: 'absolute',
      left: cx - 25,
      top: cy - 35,
      width: 50,
      height: 70,
      background: D.red,
      opacity: shardOpacity,
      transform: 'rotate(' + rot + 'deg)',
      clipPath: 'polygon(15% 0%, 85% 8%, 100% 55%, 65% 100%, 0% 75%)'
    }
  });
});

const numOpacity = interpolate(frame, [0, dur], [0.95, 0.8], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
const numGlow = interpolate(frame, [0, dur], [30, 20], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
const bigNum = e('div', {
  key: 'num',
  style: {
    position: 'absolute',
    width: '100%',
    top: height * 0.2,
    textAlign: 'center',
    fontFamily: D.font_display,
    fontSize: Math.min(width * 0.15, 160),
    fontWeight: 900,
    color: D.red,
    opacity: numOpacity,
    textShadow: '0 0 ' + numGlow + 'px ' + D.red + ', 0 0 ' + (numGlow * 2) + 'px ' + D.red,
    letterSpacing: 4
  }
}, '86%');

const letters = brandText.split('');
const letterEls = letters.map(function(ch, i) {
  const appearAt = i * framesPerLetter;
  const age = frame - appearAt;
  if (age < 0) return null;
  const coolProg = interpolate(age, [0, Math.max(1, 18)], [0, 1], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
  const letterOpacity = interpolate(age, [0, Math.max(1, 4)], [0.3, 1], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
  const glow = interpolate(coolProg, [0, 1], [35, 6], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
  const bright = interpolate(coolProg, [0, 1], [1.8, 1], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
  const hotShadow = coolProg < 0.5
    ? '0 0 ' + (glow * 1.5) + 'px ' + D.red + ', 0 0 ' + glow + 'px ' + D.amber
    : '0 0 ' + glow + 'px ' + D.amber;
  return e('span', {
    key: 'l' + i,
    style: {
      display: 'inline-block',
      fontFamily: D.font_display,
      fontSize: Math.min(width * 0.038, 46),
      fontWeight: 800,
      letterSpacing: 3,
      color: D.amber,
      opacity: letterOpacity,
      filter: 'brightness(' + bright + ')',
      textShadow: hotShadow,
      minWidth: ch === ' ' ? 14 : undefined
    }
  }, ch);
});

const validLetters = letterEls.filter(function(el) { return el !== null; });
const brandRow = e('div', {
  key: 'brand',
  style: {
    position: 'absolute',
    width: '100%',
    top: height * 0.53,
    textAlign: 'center',
    whiteSpace: 'pre'
  }
}, ...validLetters);

const shimmerY = interpolate(frame, [0, dur], [height * 0.15, height * 0.85], {extrapolateLeft:'clamp', extrapolateRight:'clamp'});
const shimmer = e('div', {
  key: 'shimmer',
  style: {
    position: 'absolute',
    left: width * 0.15,
    right: width * 0.15,
    top: shimmerY,
    height: 1,
    background: D.amber,
    opacity: 0.12
  }
});

return e('div', {
  style: { position: 'absolute', inset: 0, backgroundColor: D.bg, overflow: 'hidden' }
}, ...shards, bigNum, brandRow, shimmer);
